window.piRenderAcctAlerts = async function () {
  var box = document.getElementById('pi-acct-alerts');
  if (!box) return;
  var month = monthVal();
  box.innerHTML = '<div style="color:var(--tx3);font-size:12px">Checking Booking.com invoices vs Hosthub departures for ' + month + '…</div>';
  try {
    var j = await fetch('/api/platform-invoices/reconcile?month=' + encodeURIComponent(month)).then(function (r) { return r.json(); });
    if (j && j.error) throw new Error(j.error);
    if (j.match) {
      box.innerHTML = '<div style="border:1px solid rgba(26,127,55,.35);border-radius:10px;padding:10px 12px;font-size:12.5px;background:rgba(26,127,55,.07)"><b>' + month + '</b> — Booking.com invoices match Hosthub departures in <b>' + (j.bookMonth || '') + '</b> · ' + (j.included || 0) + ' PDF(s) across ' + (j.expected || 0) + ' expected folder(s).</div>';
      return;
    }
    var errs = j.errors || [];
    box.innerHTML = '<div style="border:1px solid rgba(185,28,28,.4);border-radius:10px;padding:10px 12px;font-size:12.5px;background:rgba(185,28,28,.06)">' +
      '<div style="font-weight:650;color:#b91c1c;margin-bottom:6px">' + month + ' — ' + errs.length + ' Booking.com reconcile alert(s). The agent will not email until these are resolved.</div>' +
      errs.map(function (e) {
        var kind = e.type === 'stays_without_invoice' ? 'Departures but no invoice' : 'Invoice but no departures';
        return '<div style="margin-top:3px">· <b>' + piAcctEsc(e.aptName || '') + '</b> — ' + kind + '. ' + piAcctEsc(e.message || '') + '</div>';
      }).join('') +
      '</div>';
  } catch (e) { box.innerHTML = '<div style="color:#b00;font-size:12px">Reconcile check failed: ' + piAcctEsc(e.message || String(e)) + '</div>'; }
};
